:7px;border-radius:50%;background:#79bdfb;box-shadow:0 0 10px #63b2ff}.team-label.away{justify-content:flex-end}.team-label.away i{background:#ff8069;box-shadow:0 0 10px #ff725e}.score{display:flex;align-items:center;gap:11px;font-family:'Barlow Condensed',sans-serif;font-size:29px;font-weight:800;letter-spacing:1px}.score b{font-size:18px;color:#71817c}.clock-wrap{display:flex;align-items:center;gap:8px;font-family:'Barlow Condensed',sans-serif;font-size:21px;font-weight:800;letter-spacing:1px}.clock-wrap small{display:block;position:absolute;margin-top:35px;margin-left:17px;font:700 8px 'DM Sans',sans-serif;color:#95a39d;letter-spacing:1.6px}.live-dot,.eyebrow span{width:7px;height:7px;background:var(--mint);border-radius:50%;box-shadow:0 0 11px #b3ed63}.match-tag{position:absolute;top:116px;left:4.4vw;z-index:3;display:flex;align-items:center;gap:10px}.tag-icon{display:grid;place-items:center;width:32px;height:32px;border:1px solid #ffffff25;border-radius:10px;color:var(--mint);font-size:16px;background:#08171383}.match-tag div,.intro-tip div{display:grid;gap:3px}.match-tag strong{font-size:9px;letter-spacing:1.3px}.match-tag small{font-size:8px;color:#afbab3;letter-spacing:1.2px}.status-pill{position:absolute;z-index:3;top:116px;right:4.4vw;padding:9px 13px;display:flex;align-items:center;gap:8px;border:1px solid #ffffff24;background:#06171292;border-radius:20px;font-size:8px;letter-spacing:1.1px;color:#dce7dc;opacity:0;transform:translateY(-5px);transition:.3s}.status-pill.visible{opacity:1;transform:none}.status-pill span{width:6px;height:6px;border-radius:50%;background:var(--mint)}.bottom-hud{position:absolute;z-index:4;bottom:0;left:0;right:0;height:112px;padding:20px 4.4vw 22px;display:flex;align-items:flex-end;justify-content:space-between;background:linear-gradient(0deg,rgba(4,14,19,.78),transparent)}.control-hint{display:flex;align-items:center;gap:5px;height:35px;color:#e5ebe7}.keycap{width:22px;height:22px;display:grid;place-items:center;border:1px so