eight:900;letter-spacing:1.1px;cursor:pointer;box-shadow:0 8px 24px #a0e54c2c;transition:transform .2s,box-shadow .2s}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 12px 28px #a0e54c55}.primary-btn b{font-size:20px;font-weight:500}.intro-foot{display:flex;align-items:center;gap:12px;margin-top:31px;color:#9eaaa5;font-size:8px;letter-spacing:1.2px;font-weight:700}.intro-foot i{width:3px;height:3px;border-radius:50%;background:var(--mint)}.intro-tip{position:absolute;right:9vw;bottom:18%;display:flex;align-items:center;gap:12px;padding:13px 18px;border:1px solid #ffffff22;border-radius:12px;background:#07171385;backdrop-filter:blur(12px)}.intro-tip>span{font:800 21px 'Barlow Condensed';color:var(--mint)}.intro-tip b{font-size:8px;letter-spacing:1.1px}.intro-tip small{color:#aab8b0;font-size:9px}.result-modal{position:absolute;z-index:7;inset:0;display:grid;place-items:center;background:#041014a8;backdrop-filter:blur(9px)}.result-modal.hidden{display:none}.result-card{width:min(90vw,410px);padding:40px 42px;text-align:center;border:1px solid #ffffff25;border-radius:20px;background:#0a1c20ee;box-shadow:0 25px 90px #0008}.result-card .eyebrow{justify-content:center}.result-card h2{font-size:48px;margin:18px 0}.result-score{display:flex;justify-content:center;align-items:center;gap:21px;font:800 55px 'Barlow Condensed';color:var(--mint)}.result-score span{font-size:28px;color:#73837b}.result-card p{color:#b4c0ba;font-size:13px;margin:5px 0 23px}.result-card .primary-btn{margin:0 auto;width:100%}.mobile-controls{display:none}.toast{position:absolute;z-index:5;left:50%;top:23%;transform:translate(-50%,-6px);padding:10px 18px;border-radius:30px;background:#081712d9;border:1px solid #ffffff26;color:white;font-size:11px;font-weight:800;letter-spacing:1px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
