import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#scene');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x10201e); scene.fog=new THREE.Fog(0x10201e,38,78);
const camera=new THREE.PerspectiveCamera(42,1,.1,120); camera.position.set(0,29,30);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1; mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdaf6ec,0x263628,2.1));
const keyLight=new THREE.DirectionalLight(0xfff4d6,3.2); keyLight.position.set(-7,22,10); keyLight.castShadow=true; keyLight.shadow.mapSize.set(2048,2048); keyLight.shadow.camera.left=-23;keyLight.shadow.camera.right=23;keyLight.shadow.camera.top=20;keyLight.shadow.camera.bottom=-20;keyLight.shadow.bias=-.0003;scene.add(keyLight);
const fill=new THREE.DirectionalLight(0x9bd9ff,1.2);fill.position.set(12,13,-12);scene.add(fill);
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const grassA=mat(0x286b3b), grassB=mat(0x327846), lineMat=new THREE.MeshBasicMaterial({color:0xd9e8d5,transparent:true,opacity:.76});
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),mat(0x142522));ground.rotation.x=-Math.PI/2;ground.position.y=-.3;ground.receiveShadow=true;scene.add(ground);
const field=new THREE.Mesh(new THREE.PlaneGeometry(32,22),grassA);field.rotation.x=-Math.PI/2;field.receiveShadow=true;field.position.y=0;scene.add(field);
// Alternating turf bands give the pitch depth without texture downloads.
for(let i=0;i<8;i++){const band=new THREE.Mesh(new THREE.PlaneGeometry(4,22),i%2?grassA:grassB);band.rotation.x=-Math.PI/2;band.position.set(-14+i*4,.012,0);band.receiveShadow=true;scene.add(band)}
function line(points,closed=false){const g=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(p[0],.035,p[1])));const o=new THREE.Line(g,lineMat);if(closed)o.geometry.setFromPoints([...points,points[0]].map(p=>new THREE.Vector3(p[0],.035,p[1])));scene.add(o);return o}
line([[-16,-11],[16,-11],[16,11],[-16,11]],true);line([[0,-11],[0,11]]);
const circlePts=[];for(let i=0;i<=80;i++){let a=i/80*Math.PI*2;circlePts.push([2.6*Math.cos(a),2.6*Math.sin(a)])}line(circlePts);
for(const side of [-1,1]){const x=side*16;line([[x,-3.3],[x-side*3,-3.3],[x-side*3,3.3],[x,3.3]]);line([[x,-6.2],[x-side*6.3,-6.2],[x-side*6.3,6.2],[x,6.2]]);const arc=[];for(let i=0;i<=30;i++){const a=(-.82+i/30*1.64);arc.push([side*10+2.25*Math.cos(a),2.25*Math.sin(a)])}line(arc)}
function box(w,h,d,material,x,y,z){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o}
// Goals, sturdy white frames with dark netting.
for(const side of [-1,1]){const gx=side*16;const goalMat=mat(0xf1f1dc,.32,.1), netMat=new THREE.MeshBasicMaterial({color:0xc9d9cf,wireframe:true,transparent:true,opacity:.22});const net=new THREE.Mesh(new THREE.BoxGeometry(1.7,2.3,4.7),netMat);net.position.set(gx+side*.8,1.15,0);scene.add(net);for(const z of [-2.3,2.3]){const post=box(.16,2.3,.16,goalMat,gx,1.15,z)}box(.16,.16,4.6,goalMat,gx,2.3,0);for(const x of [gx,gx+side*1.6]){box(.08,2.25,.08,goalMat,x,1.1,-2.3);box(.08,2.25,.08,goalMat,x,1.1,2.3)}box(1.6,.08,.08,goalMat,gx+side*.8,2.25,-2.3);box(1.6,.08,.08,goalMat,gx+side*.8,2.25,2.3)}
// Stadium surrounds, low terraces and a dotted crowd of colored seats.
const standDark=mat(0x152428), seatMats=[mat(0x29413f),mat(0x3c5149),mat(0x263947),mat(0x6a4842),mat(0x879a68)];
for(const z of [-13.3,13.3]){const terrace=new THREE.Mesh(new THREE.BoxGeometry(39,2.5,2.1),standDark);terrace.position.set(0,.15,z);terrace.receiveShadow=true;scene.add(terrace);for(let i=0;i<110;i++){const x=-18.5+(i%55)*.68,y=1.2+Math.floor(i/55)*.72;const s=new THREE.Mesh(new THREE.BoxGeometry(.38,.48,.42),seatMats[(i*7+Math.floor(i/3))%seatMats.length]);s.position.set(x,y,z+(z<0?-.2:.2));scene.add(s)}}
for(const x of [-18.2,18.2]){const wall=new THREE.Mesh(new THREE.BoxGeometry(1.5,3,28),standDark);wall.position.set(x,.5,0);scene.add(wall)}

const blueMat=mat(0x47a8ef,.46), blueDark=mat(0x1762a1,.58), coralMat=mat(0xf07862,.46), coralDark=mat(0xa94742,.58), skin=mat(0xe4b28b,.75), shoeMat=mat(0x111c1e,.48), white=mat(0xf0f0df,.55), keeperMat=mat(0xd2ed72,.46);
function createPlayer(team,x,z,index,keeper=false){
 const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);const shirt=keeper?keeperMat:(team==='blue'?blueMat:coralMat), shorts=team==='blue'?blueDark:coralDark;
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.37,.45,4,8),shirt);torso.position.y=1.02;torso.castShadow=true;group.add(torso);
 const shortsMesh=new THREE.Mesh(new THREE.CylinderGeometry(.31,.34,.3,10),shorts);shortsMesh.position.y=.56;shortsMesh.castShadow=true;group.add(shortsMesh);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),skin);head.position.y=1.72;head.castShadow=true;group.add(head);
 const hair=new THREE.Mesh(new THREE.SphereGeometry(.225,10,7,0,Math.PI*2,0,Math.PI*.48),mat(0x322c27));hair.position.y=1.78;group.add(hair);
 // subtle sleeve/arm silhouette
 for(const s of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.32,3,6),shirt);arm.position.set(s*.39,1.03,.02);arm.rotation.z=s*.17;arm.castShadow=true;group.add(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.42,3,6),skin);leg.position.set(s*.16,.28,0);leg.castShadow=true;group.add(leg);const boot=new THREE.Mesh(new THREE.BoxGeometry(.2,.13,.34),shoeMat);boot.position.set(s*.16,.08,.08);boot.castShadow=true;group.add(boot)}
 const stripe=new THREE.Mesh(new THREE.BoxGeometry(.045,.65,.016),white);stripe.position.set(.13,1.03,.355);group.add(stripe);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.52,20),new THREE.MeshBasicMaterial({color:0x07130b,transparent:true,opacity:.26,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;group.add(shadow);
 const player={group,team,index,keeper,x,z,vx:0,vz:0,dirX:team==='blue'?1:-1,dirZ:0,speed:keeper?3.5:5.25,shadow};
 if(team==='blue'&&index===0){const ring=new THREE.Mesh(new THREE.TorusGeometry(.57,.045,7,36),new THREE.MeshBasicMaterial({color:0xc9f76c,emissive:0x568b22,emissiveIntensity:.3}));ring.rotation.x=Math.PI/2;ring.position.y=.055;group.add(ring);const marker=new THREE.Mesh(new THREE.ConeGeometry(.12,.23,3),new THREE.MeshBasicMaterial({color:0xd9ff88}));marker.rotation.x=Math.PI;marker.position.y=2.19;group.add(marker);player.marker=marker}
 return player;
}
const players=[createPlayer('blue',-5,0,0),createPlayer('blue',-9,-6,1),createPlayer('blue',-9,6,2),createPlayer('blue',-12,-2.5,3),createPlayer('blue',-13,2.5,4,true),createPlayer('red',5,0,0),createPlayer('red',9,-6,1),createPlayer('red',9,6,2),createPlayer('red',12,-2.5,3),createPlayer('red',13,2.5,4,true)];
const user=players[0], opponents=players.filter(p=>p.team==='red');
const ballGroup=new THREE.Group();scene.add(ballGroup);const ball=new THREE.Mesh(new THREE.SphereGeometry(.32,20,16),mat(0xf4f3e8,.38));ball.castShadow=true;ball.receiveShadow=true;ballGroup.add(ball);
const patchMat=mat(0x182223,.42);for(let i=0;i<8;i++){const a=i/8*Math.PI*2;const patch=new THREE.Mesh(new THREE.SphereGeometry(.09,8,6),patchMat);patch.position.set(.30*Math.cos(a),.12*Math.sin(a*2),.30*Math.sin(a));patch.scale.set(.52,.75,.52);ballGroup.add(patch)}
const ballShadow=new THREE.Mesh(new THREE.CircleGeometry(.4,18),new THREE.MeshBasicMaterial({color:0x07130b,transparent:true,opacity:.35,depthWrite:false}));ballShadow.rotation.x=-Math.PI/2;ballShadow.position.y=.026;scene.add(ballShadow);
const ballState={x:-3,z:0,y:.32,vx:0,vz:0,vy:0,owner:null,cooldown:0};
